const Person = defineEntity({
  name: "Person",
  discriminatorColumn: "discr",
  discriminatorMap: { person: "Person", employee: "Employee" },
  properties: { id: p.number().primary(), name: p.string() },
});

export const Employee = defineEntity({
  name: "Employee",
  extends: Person,
  properties: { salary: p.number() },
});
